"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["阿森兄弟夺取北保加利亚；拜占庭承认第二保加利亚国家", "ff0554e9"], "d": ["彼得和阿森兄弟在库曼人的支持下重新夺取北保加利亚；依1187年和约，拜占庭承认第二保加利亚国家。", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["塞尔维亚巩固对泽塔的统治", "794c821d"], "d": ["1189年塞尔维亚巩固了对泽塔（包括科托尔海岸）的统治；泽塔被给予特殊地位。", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["居伊·德·吕西尼昂购得塞浦路斯，尼科西亚成为首都", "11017aea"], "d": ["居伊·德·吕西尼昂从圣殿骑士团手中购得该岛，并以尼科西亚为首都。", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["卡洛扬夺取瓦尔纳", "1237fe7f"], "d": ["卡洛扬沙皇率领的保加利亚人于1201年3月从拜占庭手中夺取瓦尔纳；该城在13-14世纪一直在保加利亚国家疆界之内。", "b60444f8"]},
